          "sampleSolution": "/* This program contains 2 parts: (1) and (2)\n   YOUR TASK IS TO COMPLETE THE PART  (2)  ONLY\n */\n//(1)==============================================================\nimport java.util.*;\nimport java.io.*;\n\npublic class MyList {\n\n    Node head, tail;\n\n    MyList() {\n        head = tail = null;\n    }\n\n    boolean isEmpty() {\n        return (head == null);\n    }\n\n    void clear() {\n        head = tail = null;\n    }\n\n    void fvisit(Node p, RandomAccessFile f) throws Exception {\n        if (p != null) {\n            f.writeBytes(p.info + \" \");\n        }\n    }\n\n    void ftraverse(RandomAccessFile f) throws Exception {\n        Node p = head;\n        while (p != null) {\n            fvisit(p, f); // You will use this statement to write information of the node p to the file\n            p = p.next;\n        }\n        f.writeBytes(\"\\r\\n\");\n    }\n\n    void loadData(int k) { //do not edit this function\n        String[] a = Lib.readLineToStrArray(\"data.txt\", k);\n        int[] b = Lib.readLineToIntArray(\"data.txt\", k + 1);\n        int[] c = Lib.readLineToIntArray(\"data.txt\", k + 2);\n        int n = a.length;\n        for (int i = 0; i < n; i++) {\n            addLast(a[i], b[i], c[i]);\n        }\n    }\n\n//===========================================================================\n//(2)===YOU CAN EDIT OR EVEN ADD NEW FUNCTIONS IN THE FOLLOWING PART========\n//===========================================================================\n/* \n   Khong su dung tieng Viet co dau de viet ghi chu.\n   Neu dung khi chay truc tiep se bao loi va nhan 0 diem\n     */\n    void addLast(String xProducer, int xWeight, int xPrice) { //f1\n        //You should write here appropriate statements to complete this function.\n        //--------------------------------------------------------\n        if (xWeight <= 0 || xPrice <= 0) {\n            return;\n        }\n        Node node = new Node(new Laptop(xProducer, xWeight, xPrice));\n        if (isEmpty()) {\n            head = tail = node;\n        } else {\n            tail.next = node;\n            tail = node;\n        }\n        //---------------------------------------------------------\n    }\n\n\n    //==================================================================\n    //You do not need to edit this function. Your task is to complete the \n\t//addLast function above only.\n    void f1() throws Exception {\n        clear();\n        loadData(1);\n        String fname = \"f1.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        f.close();\n    }\n\n//==================================================================\n    void f2() throws Exception {\n        clear();\n        loadData(5);\n        String fname = \"f2.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        Node v = new Node(new Laptop(\"V\", 8, 9));\n        Node w = new Node(new Laptop(\"W\", 1, 7));\n        //------------------------------------------------------------------------------------\n        /*You must keep statements pre-given in this function.\n        \n\t\tYour task is to insert statements here, just after this comment,\n        to complete the question in the exam paper.*/\n\n        // w becomes the 2nd node (index 1), v becomes the 3rd node (index 2)\n        w.next = head.next;\n        head.next = w;\n        v.next = w.next;\n        w.next = v;\n        //------------------------------------------------------------------------------------\n        ftraverse(f);\n        f.close();\n    }\n\n//==================================================================\n    void f3() throws Exception {\n        clear();\n        loadData(9);\n        String fname = \"f3.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        //------------------------------------------------------------------------------------\n        /*You must keep statements pre-given in this function.\n        \n\t\tYour task is to insert statements here, just after this comment,\n        to complete the question in the exam paper.*/\n\n        // find the LAST node with the maximum weight (ties broken by keeping the last occurrence)\n        Node p = head, maxNode = null;\n        int maxW = Integer.MIN_VALUE;\n        while (p != null) {\n            if (p.info.weight >= maxW) {\n                maxW = p.info.weight;\n                maxNode = p;\n            }\n            p = p.next;\n        }\n        // remove maxNode from the list\n        if (maxNode != null) {\n            if (maxNode == head) {\n                head = head.next;\n                if (head == null) tail = null;\n            } else {\n                Node prev = head;\n                while (prev.next != maxNode) prev = prev.next;\n                prev.next = maxNode.next;\n                if (maxNode == tail) tail = prev;\n            }\n        }\n        //------------------------------------------------------------------------------------\n        ftraverse(f);\n        f.close();\n    }\n\n//==================================================================\n    void f4() throws Exception {\n        clear();\n        loadData(13);\n        String fname = \"f4.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        //------------------------------------------------------------------------------------\n        /*You must keep statements pre-given in this function.\n        \n\t\tYour task is to insert statements here, just after this comment,\n        to complete the question in the exam paper.*/\n\n        int count = 0;\n        Node p = head;\n        while (p != null) {\n            count++;\n            p = p.next;\n        }\n        f.writeBytes(count + \"\\r\\n\");\n\n        //------------------------------------------------------------------------------------\n        f.close();\n    }\n\n//==================================================================\n    void f5() throws Exception {\n        clear();\n        loadData(17);\n        String fname = \"f5.txt\";\n        File g123 = new File(fname);\n        if (g123.exists()) {\n            g123.delete();\n        }\n        RandomAccessFile f = new RandomAccessFile(fname, \"rw\");\n        ftraverse(f);\n        //------------------------------------------------------------------------------------\n        /*You must keep statements pre-given in this function.\n        \n\t\tYour task is to insert statements here, just after this comment,\n        to complete the question in the exam paper.*/\n\n        // remove the first node\n        if (head != null) {\n            head = head.next;\n            if (head == null) tail = null;\n        }\n        // sort remaining nodes ascending by weight (selection sort, swap info only)\n        Node a = head;\n        while (a != null) {\n            Node minNode = a;\n            Node b = a.next;\n            while (b != null) {\n                if (b.info.weight < minNode.info.weight) minNode = b;\n                b = b.next;\n            }\n            if (minNode != a) {\n                Laptop tmp = a.info;\n                a.info = minNode.info;\n                minNode.info = tmp;\n            }\n            a = a.next;\n        }\n\n        //------------------------------------------------------------------------------------\n        ftraverse(f);\n        f.close();\n    }\n\n}\n"